  o_quiet: "Leiseste Momente (empfohlen)", o_median: "Typischer Pegel", o_min: "Leisester Wert (Minimum)", o_mean: "Durchschnitt", o_max: "Lautester Wert (Maximum)",
  f_rise_s: "Anpassung, wenn es lauter wird (s)", h_rise_s: "Groß = Lärm zieht die Schwelle kaum mit.",
  f_fall_s: "Anpassung, wenn es leiser wird (s)", h_fall_s: "Klein = folgt schnell, wenn es ruhiger wird.",
  f_min_event_ms: "Mindestdauer (ms)", h_min_event_ms: "0 = jeder Klopfer zählt. 40–60 filtert Knackser.",
  f_pre_roll_s: "Vorlauf (s)", h_pre_roll_s: "So viele Sekunden vor der Störung wertet die KI mit aus.",
