  n_note: "Curve = typical level per minute (smoothed), thin line = peaks, dashed = threshold. “Undisturbed” refers to the recorded time only. Tap an event to view it. The report is always built from the stored data; deleted data is missing from it.",
   del_sel: "Delete selected entries", actions: "Actions", m_download: "Download noise track", m_delete: "Delete entry", m_select: "Select", m_unselect: "Unselect", confirm_del_ev: "Permanently delete this entry including its noise track?", confirm_del_evs: "Permanently delete {n} entries including their noise tracks?", sel_none: "Clear selection", sel_all: "Select all", sel_count: "{n} entr(y/ies) selected",
   
   del_note: "Menu ⋮ or right-click a row: download noise track or delete entry. When deleting, the entry disappears from the list; for safety the old state is kept as log_vor_loeschen_….csv, the row goes to geloescht.csv and the files to the trash clips/geloescht.",
  s_sources: "Sources (microphones)", add_phone: "Phone (browser)", add_url: "Phone app / stream URL", add_phone_short: "Add phone",
  type_local: "Server microphone", type_phone: "Phone · browser", type_url: "Stream URL",
