  dt_title: "Course (level every 125 ms)", dt_reset: "Whole period", lev_title: "Events today", lev_n: "{n} events", lev_none: "No events today yet.", lev_sel: "Selected device", lev_cols: "Choose columns", dt_left: "Back", dt_right: "Forward", dt_zin: "Zoom in", dt_zout: "Zoom out", dt_hint: "Mouse wheel/touchpad, drag a range, + / − or two fingers = zoom time; when zoomed: drag, ‹ ›, swipe sideways or the bar = move (Shift + drag = select range); Shift + mouse wheel or wheel over the dB labels = zoom height (bottom-aligned); double click or “Whole period” = everything. Hover over or tap a disturbance = details. area = peak, red = disturbance, grey = background, dashed = threshold, blue = on according to Home Assistant.", dt_none: "There is no whole-day recording (yet) for this day and device.", dt_at: "{t} · peak {p} dBFS · background {b} dBFS",
