  pf_ok_tip: "Profile confirmed by you", pf_auto_tip: "Assigned by the AI (similarity) – confirm or change in the event", pf_bg_short: "background", grp_n: "{n} disturbances", devs_col: "Devices (peak)", ev_v_grp: "Groups", ev_v_all: "All single", scan_btn: "Profiles & re-scan", pf_title: "Profiles", pf_teach: "Record sound profile", pf_teach_hint: "Enter a name, press “Start”: for 3 s the quiet level of every device is measured. Then make the sound (e.g. slam the door) – every peak above the quiet level is recorded per device as an example, also several times in a row. After 2 min without sound it stops by itself. No sound is stored.", pf_name_ph: "Name, e.g. “door slam” or “TV”", pf_go: "Start", pf_stop: "Done", pf_apply: "Apply", pf_drop: "Discard", pf_list: "Learned profiles", scan_title: "Re-scan", scan_hint: "Searches the stored data of the period with the profiles: every disturbance gets its profile (ones you confirmed stay), and the day recording is marked also below the threshold. After learning new profiles simply start again. Sensors (Home Assistant, phone as motion sensor) stay untouched.", scan_prof: "Profile", scan_ev: "Assign disturbances", scan_ar: "Mark continuously (also below threshold)", scan_go: "Re-scan", pf_teach_btn: "Record sound profile", scan_all: "all profiles", scan_per: "Period: {r}", pf_n: "{n} examples", pf_bg_tip: "Background / own device (e.g. own TV): stays visible but does not count as a disturbance", pf_bg: "Background", pf_none: "No profiles yet. Use “Record sound profile” above – or name a range in an event.", pf_ren_q: "New name:", pf_del_q: "Delete profile “{n}”? Named ranges in events stay.", pf_quiet: "Measuring quiet level … please be quiet ({s} s)", pf_armed: "Ready – make the sound now (also several times). {n} example(s) so far · stops after {s} s without sound", pf_done: "{n} example(s) recorded – check and apply", pf_heard: "heard ({d} dB)", pf_not_heard: "not heard", pf_busy: "Already running.", pf_saved: "{n} example(s) saved. Tip: then “Re-scan”.", pf_drop_q: "Discard recording?", scan_run: "Running … {p} % · {e} disturbances assigned · {a} ranges", scan_noprof: "No profiles with examples.", scan_done: "Done: {e} disturbances assigned, {a} ranges marked.", pf_none_ev: "no profile", pf_confirm: "Confirm", pf_change: "Profile:", pf_none_opt: "– none –", fnp_to_ev: "→ to the disturbance {t} ({d}) {k}", fnp_saved_ev: "Note saved – to the disturbance {t}", run_chain_bad: "Data chain does not match from: {l} – the day recording was changed afterwards or is damaged", run_chain_none: "Data chain: no checksums for this period yet (recorded before version 1.40)", run_chain_ok: "Data chain checked: day recording complete and unchanged ({n} device-days)", run_down: "Not recorded {a} – {b} ({r}, then version {v})", run_gap: "Not recorded {a} – {b}: {s} (gap in the day recording, cause not logged – e.g. moving to a new installation)", run_r_update: "update", run_r_restart: "stopped / restarted by Home Assistant", run_update: "Update {a}: {o} → {n} (recording continued)", run_fallback: "{a}: version {v} did not start, back to {b}", run_crash: "{a}: program {v} restarted (recording continued)", f_fp_store: "Store AI fingerprint continuously", h_fp_store: "Once per second when something can be heard: the AI's numbers (no sound, not reversible). Makes “Re-scan” more accurate. About 2–10 MB per device and day.", t_fp_store: "The AI listens to the sound in memory and computes a short series of numbers describing how the sound sounds to it. Only these numbers are stored. Neither sound nor speech can be recovered from them.", f_group_pause_s: "Group: max. pause (s)", h_group_pause_s: "Disturbances of the same type or profile with at most this gap are shown as a group in the list.", f_fn_assign_min: "Assign note: up to (min) after the disturbance", h_fn_assign_min: "Note without its own time: if there was a disturbance within these minutes before, the note belongs to it (0 = never).", ha_mute: "muted", s_prof: "Teach the AI (profiles)", h_prof: "Teach your own sounds (e.g. “door slam”, “TV”): a moment of quiet, then make the sound – every device learns its own example. Disturbances are then assigned to the profile; “Re-scan” applies it to stored data.", t_prof: "No sound is stored, only measurements (spectrum, level curve) and the AI fingerprint of the peak.", s_prof_list: "Manage profiles & re-scan", s_reset: "Reset", h_reset: "Deletes the selected parts permanently. Devices and their connections are always kept. Best download a backup first.", rs_data: "Measurements & disturbances (day recording, levels, spectrum, fingerprint, disturbances, AI results, checksums, videos, audio)", rs_notes: "Notes, log lists, named ranges", rs_profiles: "Sound profiles", rs_settings: "Settings to default (thresholds, times, time profiles, Home Assistant rules, own device settings)", rs_go: "Reset …", rs_backup_q: "Download a backup first?", rs_nobackup: "Reset without backup", rs_now: "Reset now", rs_after_dl: "Backup is downloading – when it is finished, press “Reset now”.", rs_q1: "Really reset? Deleted: {p}", rs_q2: "Reset without backup? Permanently deleted: {p}", rs_running: "Resetting …", rs_done: "Reset done – reloading the page …", rs_none: "Please select at least one part.", s_wav: "Store real audio (not recommended)", h_wav: "Please leave this off. Levels, spectrum, time, AI classification, room comparison and your notes are enough as evidence – all of it is stored without sound. Why no sound: an audio recording can contain other people’s conversations (neighbours, stairwell, visitors). Recording non-public speech can be a criminal offence (in Germany § 201 StGB); with a recording directed at the neighbourhood this is foreseeable. Secret audio recordings are usually not admissible in court and can harm your credibility. Audio also needs a lot of storage. Not legal advice – ask a lawyer if in doubt.", fn_btn: "Note now", fnp_run: "still going (to = when saving)", fn